# GraphQL Schema
type User {
  id: ID!
  name: String!
  email: String!
  posts: [Post!]!
}

type Post {
  id: ID!
  title: String!
  content: String!
  author: User!
}

type Query {
  user(id: ID!): User
  posts(limit: Int, offset: Int): [Post!]!
}

# Query example
query {
  user(id: "123") {
    name
    email
    posts {
      title
      content
    }
  }
}

// Resolver with DataLoader to solve N+1
@Component
public class UserResolver implements GraphQLResolver<User> {
    public List<Post> posts(User user, DataLoader<Long, List<Post>> postLoader) {
        return postLoader.load(user.getId()); // Batches queries
    }
}
